input TambahBukuInput {
  judul: String!
  harga: Int!
}
type Mutation {
  tambahBuku(input: TambahBukuInput!): Buku!
}

tambahBuku: (_, { input }) => {
  if (!input.judul.trim())
    throw new Error("Judul wajib diisi");
  if (input.harga <= 0)
    throw new Error("Harga harus lebih dari 0");
  const buku = { id: BUKU.length + 1, ...input };
  BUKU.push(buku);
  return buku;
},

